name = "Riyaz"
print(len(name)) #len() function is used to get the length of a string in python. It returns the number of characters in the string.
print(name.endswith("z")) #endswith() function is used to check if a string ends with a specific character or substring. It returns True if the string ends with the specified character or substring, otherwise it returns False.
print(name.startswith("R")) #startswith() function is used to check if a string starts with a specific character or substring. It returns True if the string starts with the specified character or substring, otherwise it returns False.
print(name.upper()) #upper() function is used to convert a string to uppercase. It returns a new string with all the characters in uppercase.
print(name.lower()) #lower() function is used to convert a string to lowercase. It returns a new string with all the characters in lowercase.       
print(name.replace("Riyaz", "Riyaz Qureshi")) #replace() function is used to replace a specific character or substring in a string with another character or substring. It returns a new string with the specified character or substring replaced.
print(name.split(" ")) #split() function is used to split a string into a list of substrings based on a specific character or substring. It returns a list of substrings.
print(name.find("Riyaz")) #find() function is used to find the index of a specific character or substring in a string. It returns the index of the first occurrence of the specified character or substring, otherwise it returns -1.
print(name.count("Riyaz")) #count() function is used to count the number of occurrences of a specific character or substring in a string. It returns the number of occurrences of the specified character or substring.